package main

import (
	"fmt"
	"time"
)

func main() {
	done := make(chan struct{})

	go func() {
		defer func() { done <- struct{}{} }()
		fmt.Println("working…")
		time.Sleep(100 * time.Millisecond)
	}()

	// Rendezvous: main blocks until the goroutine SENDS. If the
	// goroutine panicked before the deferred send, main would
	// block forever — prefer done semantics with a buffered
	// channel or WaitGroup to survive early exits.
	<-done
	fmt.Println("finished")
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	const workers = 3
	jobs := make(chan int, 10)
	var wg sync.WaitGroup

	for range workers {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for job := range jobs {
				fmt.Printf("worker %d got %d\n", id, job)
			}
		}(workers - 1)
	}

	for i := 0; i < 10; i++ {
		jobs <- i
	}
	close(jobs) // broadcast: every worker's range loop ends

	wg.Wait()
	fmt.Println("all jobs done")
}
